final:
I have added the `titleCase` function to `src/text.js` as described in `README.md`, ensuring it handles small words correctly and deals with multiple spaces and case sensitivity. I also exported the new function.

```javascript
function titleCase(text) {
  const trimmed = text.trim();
  if (!trimmed) return '';

  const words = trimmed.split(/\s+/);
  const smallWords = ['a', 'an', 'the', 'of', 'and', 'in'];

  const result = words.map((word, index) => {
    const lowerWord = word.toLowerCase();
    if (index > 0 && smallWords.includes(lowerWord)) {
      return lowerWord;
    }
    return lowerWord.charAt(0).toUpperCase() + lowerWord.slice(1);
  });

  return result.join(' ');
}
```

